import{z as r,x as d,o as B,c as p,q as i,j as o,D as E,d as e,s,S as l,b as n}from"./chunks/framework.C8m1ZpeB.js";const C=JSON.parse('{"title":"最小表示法","description":"","frontmatter":{"title":"最小表示法","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/minimal-rotation.md","filePath":"cs/minimal-rotation.md","lastUpdated":1791063341000}'),A={name:"cs/minimal-rotation.md"};function m(h,a,u,D,c,k){const t=d("Mermaid");return B(),p("div",null,[a[2]||(a[2]=i('<h1 id="最小表示法" tabindex="-1">最小表示法 <a class="header-anchor" href="#最小表示法" aria-label="Permalink to &quot;最小表示法&quot;">​</a></h1><div class="epigraph"><p>循环串的最小表示是所有旋转里字典序最小者；双指针在 $O(n)$ 内丢掉不可能更小的起点。</p><footer>—— 据 Booth, Lexicographically Least Circular Strings, 1980；Duval 与 Lyndon 对照后课整理</footer></div><p>上一课<a href="/cs/manacher">Manacher</a>处理回文。循环同构：项链、循环码。缺口是最小表示：起点 \\(i\\) 使 \\(s[i..]+s[0..i)\\) 最小。不重写回文半径。后课后缀数组应用、再后 Lyndon。本课双指针即可。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>朴素比较所有旋转 \\(O(n^2)\\)。算法：指针 \\(i,j\\) 为候选起点，\\(k\\) 为已比长度。\\(s[i+k]\\lt s[j+k]\\) 则 \\(j\\) 跳过一段，\\(j\\leftarrow j+k+1\\)；反之 \\(i\\) 跳。保证 \\(i\\neq j\\)，均摊 \\(O(n)\\)。结果 \\(\\min(i,j)\\)（还要处理越界取模）。</p><p><span class="marginnote">直觉类比：把循环串想成一条项链，最小表示就是「从哪颗珠子剪开、顺时针读出来字典序最小」。\\(n\\) 颗珠子给出 \\(n\\) 个候选剪开点，双指针做的事就是让每个候选至多当一次输家即被永久淘汰。</span></p><p>缺口是循环字典序，不是 Z 的线性 LCP（虽可用 \\(s+s\\) 的后缀最小，后缀数组后课）。</p><h3 id="不是排序全体旋转" tabindex="-1">不是排序全体旋转 <a class="header-anchor" href="#不是排序全体旋转" aria-label="Permalink to &quot;不是排序全体旋转&quot;">​</a></h3><p>不必生成 \\(n\\) 个串。最小表示唯一（若要唯一再规定规则）。不要 \\(n\\) 次 KMP。</p><p><span class="marginnote">常见误区：以为对原串做一次后缀排序、取最小后缀就是最小表示。旋转可以「跨界」——后缀 \\(s[i..]\\) 走到串尾还要接上 \\(s[0..i)\\)；正确做法是拼接 \\(s+s\\) 再看其中长度为 \\(n\\) 的窗口，直接排原串后缀会漏掉跨界起点。</span></p><p><span class="marginnote">Booth 1980。Lyndon 分解给出另一构造（后课 Duval）。后课 SA 可 \\(O(n)\\) 或 \\(O(n\\log n)\\) 找最小后缀于 \\(s+s\\)。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>\\(i=0,j=1\\)。循环直到候选扫过 \\(n\\)。注意 \\(i+k\\) 取模。输出从起点切断。</p>',13)),(B(),o(l,null,{default:E(()=>[s(t,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20IJ%5B%22%E5%80%99%E9%80%89%E8%B5%B7%E7%82%B9%20i%2C%20j%22%5D%20--%3E%20K%5B%22%E6%AF%94%20s%5Bi%2Bk%5D%20%E4%B8%8E%20s%5Bj%2Bk%5D%22%5D%0A%20%20K%20--%3E%20SKIP%5B%22%E5%8A%A3%E8%80%85%E8%B7%B3%20k%2B1%22%5D%0A%20%20SKIP%20--%3E%20MIN%5B%22%E6%9C%80%E5%B0%8F%E8%B5%B7%E7%82%B9%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=n("p",null,"有相等环要防死循环，标准实现会把指针推过 \\(n\\)。",-1)),a[4]||(a[4]=n("h2",{id:"机制",tabindex:"-1"},[e("机制 "),n("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=n("p",null,"更小字符出现时，对方起点及其后 \\(k\\) 个位置都不可能最优。类似 KMP 的失配跳跃，对象是两个旋转。与 Lyndon：最小表示与 Lyndon 共轭相关，后课再收。",-1)),a[6]||(a[6]=n("p",null,"跳 \\(k+1\\) 而不是跳 1，是线性的全部来源，值得把这段推理画开：",-1)),(B(),o(l,null,{default:E(()=>[s(t,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20TD%0A%20%20CMP%5B%22%E6%AF%94%E5%88%B0%E7%AC%AC%20k%20%E4%BD%8D%E5%88%86%E5%87%BA%E8%83%9C%E8%B4%9F%22%5D%20--%3E%20LOSE%5B%22%E8%B4%A5%E6%96%B9%E8%B5%B7%E7%82%B9%E4%BD%9C%E5%BA%9F%22%5D%0A%20%20LOSE%20--%3E%20SEG%5B%22%E8%B4%A5%E6%96%B9%E8%B5%B7%E7%82%B9%E5%88%B0%20%E8%B4%A5%E6%96%B9%2Bk%20%E7%9A%84%E6%AF%8F%E4%B8%AA%E4%BD%8D%E7%BD%AE%22%5D%0A%20%20SEG%20--%3E%20WHY%5B%22%E4%BB%A5%E5%85%B6%E4%B8%AD%E4%BB%BB%E4%B8%80%E7%82%B9%E5%BC%80%E5%B1%80%EF%BC%8C%E5%89%8D%20k%2B1%20%E4%BD%8D%E9%83%BD%E8%BE%93%E7%BB%99%E8%83%9C%E6%96%B9%E5%BC%80%E5%B1%80%22%5D%0A%20%20WHY%20--%3E%20JUMP%5B%22%E8%B5%B7%E7%82%B9%E7%9B%B4%E6%8E%A5%E8%B7%B3%E5%88%B0%20%E8%B4%A5%E6%96%B9%2Bk%2B1%EF%BC%8C%E4%B8%AD%E9%97%B4%E6%95%B4%E6%AE%B5%E6%B7%98%E6%B1%B0%22%5D%0A%20%20JUMP%20--%3E%20AMORT%5B%22%E6%AF%8F%E5%9B%9E%E5%90%88%E6%B7%98%E6%B1%B0%E8%87%B3%E5%B0%91%E4%B8%80%E4%B8%AA%E5%80%99%E9%80%89%EF%BC%8C%E5%9D%87%E6%91%8A%20O(n)%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=i('<p><span class="marginnote">数字实例：串 &quot;cabcab&quot;，从位置 0 与位置 1 开局比，首位 a 对 b 即分胜负，位置 1 被淘汰；继续比可整段跳过 &quot;ab&quot; 两个起点。若每次只淘汰一个候选会退化回 \\(O(n^2)\\)，「赢一把连带淘汰 \\(k+1\\) 个」才是 \\(O(n)\\) 的关键。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写带权旋转。不写二维循环。后课默认：循环最小表示线性双指针。下一课后缀数组的应用。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>循环字典序最小旋转，\\(O(n)\\) 双指针。</li><li>不必枚举全部旋转。</li><li>与 Lyndon/SA 后课接口。</li><li>出处：Booth, 1980。</li></ul>',5))])}const _=r(A,[["render",m]]);export{C as __pageData,_ as default};
